"""Atomic paper status and a small read-only dashboard with no file browsing."""
import json,time,math,threading,html,datetime as dt
from pathlib import Path
from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
from engine import day
def percentiles(values):
 v=sorted(x for x in values if x is not None and math.isfinite(x))
 def q(p):return round(v[min(len(v)-1,int((len(v)-1)*p))],3) if v else None
 return dict(n=len(v),p50=q(.5),p90=q(.9),p95=q(.95),p99=q(.99),max=q(1))
def summary(store):
 db=store.db;now=time.time();cfg=store.cfg;out=dict(mode='PAPER ONLY',strategy='Adaptive tennis · 90-second score state',generated=now,started=store.meta('started'),clock=store.meta('clock'),heartbeat=store.meta('heartbeat'),catalogue_last_success=store.meta('catalogue_last_success'),config_hash=store.meta('config_hash'),portfolios={})
 for scenario in ('base','stress'):
  p=store.portfolio(scenario,now);rs=sorted(p['settled'],key=lambda r:(r['settled'],r['id']));eq=peak=dd=0.;daily={}
  for r in rs:eq+=r['net'];peak=max(peak,eq);dd=max(dd,peak-eq);d=day(r['entered']);daily[d]=daily.get(d,0)+r['net']
  trials=db.execute('SELECT count(*) FROM attempts WHERE scenario=?',(scenario,)).fetchone()[0];unfilled=dict(db.execute("SELECT coalesce(reason,'unknown'),count(*) FROM attempts WHERE scenario=? AND status='unfilled' GROUP BY reason",(scenario,)).fetchall())
  out['portfolios'][scenario]=dict(starting_cash=100,cash=round(p['cash'],5),reserved=round(p['reserved'],5),free_cash=round(p['free_cash'],5),settled=len(rs),open=len(p['active']),pending=len(p['pending']),wins=sum(r['payout']==1 for r in rs),losses=sum(r['payout']==0 for r in rs),scalar=sum(r['payout'] not in (0,1) for r in rs),net=round(eq,5),realized_drawdown=round(dd,5),fees=round(sum(r['fee'] for r in rs),5),friction=round(sum(r['friction'] for r in rs),5),daily_net=daily,attempts=trials,unfilled=unfilled,filled=len(rs)+len(p['active']),trades_per_calendar_day=(len(rs)+len(p['active']))/max(1,(now-out['started'])/86400))
 pts=[dict(r) for r in db.execute('SELECT source,first_seen,lower_delay,upper_delay,censored,revision FROM points')];lat=[r['upper_delay'] for r in pts if not r['censored'] and not r['revision'] and r['upper_delay']>=0]
 out['feed']=dict(observed_point_versions=len(pts),initial_or_gap_censored=sum(r['censored'] for r in pts),revised_versions=sum(r['revision'] for r in pts),delay_upper_bound_seconds=percentiles(lat),fraction_first_received_after_90s=sum(x>90 for x in lat)/len(lat) if lat else None,fraction_after_120s=sum(x>120 for x in lat)/len(lat) if lat else None,polling_uncertainty_seconds=cfg['score_poll_seconds'])
 out['http_duration_seconds']=percentiles([r[0] for r in db.execute('SELECT duration FROM receipts WHERE received>?',(now-86400,))]);out['http_errors_24h']=db.execute('SELECT count(*) FROM receipts WHERE received>? AND error IS NOT NULL',(now-86400,)).fetchone()[0]
 out['decision_reasons']=dict(db.execute('SELECT reason,count(*) FROM decisions GROUP BY reason').fetchall());out['book_checks']=db.execute('SELECT count(*) FROM book_checks').fetchone()[0]
 out['events']=[]
 for r in db.execute('SELECT * FROM events WHERE done=0 ORDER BY start'):
  info=json.loads(r['info']);prior=json.loads(r['prior']) if r['prior'] else None;out['events'].append(dict(event=r['event'],series=r['series'],title=info['milestone'].get('title'),start=r['start'],prior='validated' if prior and prior.get('validated') else 'captured; awaiting first point' if prior and not prior.get('invalid') else prior.get('invalid') if prior else 'awaiting prospective pre-match quote',last_score_poll=r['last_poll']))
 out['recent_trades']=[dict(r) for r in db.execute('SELECT scenario,event,ticker,side,entered,price,fee,friction,settled,payout,net FROM positions ORDER BY id DESC LIMIT 30')]
 out['recent_errors']=[dict(r) for r in db.execute("SELECT at,kind,event,detail FROM health WHERE kind IN ('http_failure','match_error','catalogue_failure','execution_error','fee_changed') ORDER BY id DESC LIMIT 10")]
 elapsed=(now-out['started'])/86400;settled=out['portfolios']['base']['settled'];out['review']=dict(elapsed_days=round(elapsed,3),minimum_days=cfg['review_min_days'],minimum_settled=cfg['review_min_settled'],sample_ready=elapsed>=cfg['review_min_days'] and settled>=cfg['review_min_settled'],new_entries_end=out['started']+86400*cfg['stop_new_entries_days'],verdict='Insufficient forward evidence' if elapsed<cfg['review_min_days'] or settled<cfg['review_min_settled'] else 'Sample ready for independent review; no automatic promotion')
 out['fill_definition']='Depth-supported simulated fills: one contract must exist inside the cap in two subsequent public books. No exchange order or actual fill is sent.'
 out['feed_definition']='First-received minus provider point timestamp; includes polling and request delay. Startup/backfill, long gaps and revisions excluded from latency estimates. Provider clock accuracy is not independently verified.'
 return out
def write_status(store,root):
 data=summary(store);p=Path(root)/'status.json';tmp=p.with_suffix('.json.tmp');tmp.write_text(json.dumps(data,indent=2,allow_nan=False)+'\n');tmp.replace(p);return data
PAGE='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Tennis paper research</title><style>
body{margin:0;background:#0c1423;color:#e8eef8;font:15px system-ui,sans-serif}main{max-width:1120px;margin:auto;padding:36px 24px}h1{font-size:28px;margin-bottom:8px}h2{font-size:18px;margin-top:32px}.sub{color:#99abc6;line-height:1.6}.pill{font-weight:700;color:#66e0bc;font-size:12px;letter-spacing:1px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:16px;margin:24px 0}.card{border:1px solid #29384f;background:#142037;padding:20px;border-radius:12px}.num{font-size:30px;font-weight:700;margin:8px 0}table{width:100%;border-collapse:collapse}th,td{text-align:left;border-bottom:1px solid #29384f;padding:12px 8px}th{color:#99abc6;font-size:12px}a{color:#83baff}.scroll{overflow:auto}.warning{background:#3e301a;color:#ffdc95;padding:12px;border-radius:8px}code{font-size:12px}.small{font-size:12px;color:#99abc6}</style><main><span class="pill">PAPER RESEARCH · NO REAL ORDERS</span><h1>Adaptive tennis</h1><div class="sub">Frozen 90-second score design · ATP + WTA · 1 contract per match · $100 simulated bankroll per scenario</div><p id="health" class="sub">Loading…</p><div class="cards" id="cards"></div><p id="verdict" class="warning"></p><h2>Observed feed timing</h2><p id="feed" class="sub"></p><p class="small">Latency uses first arrival at this server. Startup history and long polling gaps are excluded. Paper fills require two subsequent books with sufficient depth; they are not actual exchange executions.</p><h2>Upcoming and active matches</h2><div class="scroll"><table><thead><tr><th>MATCH</th><th>SCHEDULED START</th><th>PRE-MATCH INPUT</th><th>LAST SCORE POLL</th></tr></thead><tbody id="events"></tbody></table></div><h2>Recent paper trades</h2><div class="scroll"><table><thead><tr><th>SCENARIO</th><th>MARKET</th><th>SIDE / PRICE</th><th>RESULT</th></tr></thead><tbody id="trades"></tbody></table></div><h2>Entry decisions</h2><div id="reasons" class="sub"></div><p class="small">Normal: 3-second execution delay + 1¢ allowance. Stress: 60-second delay + 2¢ allowance. Both include modeled fees. Drawdown is realized, not intramatch marked-to-market.</p></main><script>
const esc=x=>String(x??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const date=x=>x?new Date(x*1000).toLocaleString():'—';const money=x=>'$'+Number(x).toFixed(2);async function refresh(){try{let s=await(await fetch('/status.json',{cache:'no-store'})).json();document.querySelector('#health').textContent='Updated '+date(s.generated)+' · '+((Date.now()/1000-s.heartbeat)<30?'Observer running':'Heartbeat stale')+' · '+(s.clock?.ntp_synchronized?'Clock synchronized':'Clock check required');document.querySelector('#cards').innerHTML=Object.entries(s.portfolios).map(([k,v])=>'<div class="card"><div>'+esc(k==='base'?'Normal execution':'Delayed execution stress')+'</div><div class="num">'+money(v.net)+'</div><div class="sub">'+v.settled+' settled · '+v.wins+' wins / '+v.losses+' losses<br>'+v.open+' open · '+v.pending+' pending<br>'+v.attempts+' attempts · '+v.filled+' paper fills<br>Realized drawdown '+money(v.realized_drawdown)+'</div></div>').join('');document.querySelector('#verdict').textContent=s.review.verdict+' — '+s.review.elapsed_days.toFixed(1)+' / '+s.review.minimum_days+' days, '+s.portfolios.base.settled+' / '+s.review.minimum_settled+' settled trades.';let f=s.feed.delay_upper_bound_seconds;document.querySelector('#feed').textContent=f.n?f.n+' eligible updates · median '+f.p50+'s · 95th percentile '+f.p95+'s · '+(100*s.feed.fraction_first_received_after_90s).toFixed(1)+'% arrived after90s · '+s.feed.revised_versions+' revised records':'Waiting for new points observed prospectively. Old returned points do not count as measured live delay.';document.querySelector('#events').innerHTML=s.events.map(e=>'<tr><td>'+esc(e.title)+'</td><td>'+date(e.start)+'</td><td>'+esc(e.prior)+'</td><td>'+date(e.last_score_poll)+'</td></tr>').join('');document.querySelector('#trades').innerHTML=s.recent_trades.map(r=>'<tr><td>'+esc(r.scenario)+'</td><td>'+esc(r.ticker)+'</td><td>'+esc(r.side)+' '+money(r.price)+'</td><td>'+(r.settled?money(r.net):'Pending settlement')+'</td></tr>').join('');document.querySelector('#reasons').textContent=Object.entries(s.decision_reasons).map(([k,v])=>k+': '+v).join(' · ')||'Waiting for eligible matches.';}catch(e){document.querySelector('#health').textContent='Status unavailable: '+e.message;}}refresh();setInterval(refresh,10000);
</script></html>'''
def serve(root,port=8516):
 root=Path(root)
 class Handler(BaseHTTPRequestHandler):
  def do_GET(self):
   if self.path in ('/','/index.html'):body=PAGE.encode();kind='text/html; charset=utf-8'
   elif self.path=='/status.json':
    try:body=(root/'status.json').read_bytes();kind='application/json'
    except FileNotFoundError:self.send_error(503);return
   else:self.send_error(404);return
   self.send_response(200);self.send_header('Content-Type',kind);self.send_header('Cache-Control','no-store');self.send_header('Content-Length',str(len(body)));self.end_headers();self.wfile.write(body)
  def log_message(self,*args):pass
 server=ThreadingHTTPServer(('0.0.0.0',port),Handler);threading.Thread(target=server.serve_forever,daemon=True).start();return server
